CREATE OR REPLACE TRIGGER trg_cat_sala_room_code_ro
BEFORE UPDATE OF room_code ON cat_sala
FOR EACH ROW
BEGIN
    IF NVL(:NEW.room_code, '@@NULL@@') <> NVL(:OLD.room_code, '@@NULL@@') THEN
        RAISE_APPLICATION_ERROR(-20031, 'El codigo de la sala no puede modificarse tras el alta');
    END IF;
END;

CREATE OR REPLACE TRIGGER trg_cat_oficina_desactivar
AFTER UPDATE ON cat_oficina
DECLARE
    l_count NUMBER;
BEGIN
    SELECT COUNT(*)
      INTO l_count
      FROM cat_oficina o
     WHERE o.is_active = 'N'
       AND EXISTS (SELECT 1
                     FROM cat_sala s
                    WHERE s.office_id = o.office_id
                      AND s.is_active = 'Y');

    IF l_count > 0 THEN
        RAISE_APPLICATION_ERROR(-20030, 'No se puede desactivar una oficina con salas activas');
    END IF;

    SELECT COUNT(*)
      INTO l_count
      FROM cat_oficina o
     WHERE o.is_active = 'Y';

    IF l_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20032, 'Debe permanecer al menos una oficina activa');
    END IF;
END;

CREATE OR REPLACE TRIGGER trg_cat_sala_oficina_activa
BEFORE INSERT OR UPDATE OF office_id, is_active ON cat_sala
FOR EACH ROW
DECLARE
    l_is_active CHAR(1);
BEGIN
    IF :NEW.is_active = 'Y' THEN
        SELECT o.is_active
          INTO l_is_active
          FROM cat_oficina o
         WHERE o.office_id = :NEW.office_id;

        IF l_is_active = 'N' THEN
            RAISE_APPLICATION_ERROR(-20033, 'La oficina seleccionada no existe o esta inactiva');
        END IF;
    END IF;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE_APPLICATION_ERROR(-20033, 'La oficina seleccionada no existe o esta inactiva');
END;
